CREATE OR REPLACE FUNCTION public.search_profiles(_q text,_limit integer DEFAULT 12) RETURNS TABLE(id uuid,username text,display_name text,avatar_url text,followers bigint) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,p.username,p.display_name,p.avatar_url,(SELECT count(*) FROM profile_follows f WHERE f.following_id=p.id) FROM profiles p WHERE length(trim(coalesce(_q,'')))>1 AND (p.username ILIKE '%'||left(trim(_q),100)||'%' OR coalesce(p.display_name,'') ILIKE '%'||left(trim(_q),100)||'%') ORDER BY 5 DESC LIMIT greatest(1,least(coalesce(_limit,12),40)) $$;
CREATE OR REPLACE FUNCTION public.voice_people(_q text DEFAULT '',_admin boolean DEFAULT false) RETURNS TABLE(id uuid,username text,display_name text,avatar_url text,followers bigint,badge text) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF _admin AND NOT public.is_main_admin(auth.uid()) THEN RAISE EXCEPTION 'Owner access only'; END IF; RETURN QUERY SELECT p.id,p.username,p.display_name,p.avatar_url,(SELECT count(*) FROM profile_follows f WHERE f.following_id=p.id),b.badge FROM profiles p LEFT JOIN voice_user_badges b ON b.user_id=p.id WHERE p.username IS NOT NULL AND (trim(coalesce(_q,''))='' OR p.username ILIKE '%'||left(trim(_q),100)||'%' OR p.display_name ILIKE '%'||left(trim(_q),100)||'%') ORDER BY CASE b.badge WHEN 'golden' THEN 0 WHEN 'verified' THEN 1 ELSE 2 END,5 DESC,p.id LIMIT CASE WHEN trim(coalesce(_q,''))='' AND NOT _admin THEN 5 ELSE 40 END; END $$;
CREATE OR REPLACE FUNCTION public.guard_follow_request() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM profiles WHERE id=NEW.target_id AND NOT is_public) THEN RAISE EXCEPTION 'Private account unavailable'; END IF; IF EXISTS(SELECT 1 FROM profile_follows WHERE follower_id=NEW.requester_id AND following_id=NEW.target_id) THEN RAISE EXCEPTION 'Already following'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_follow_request BEFORE INSERT ON public.follow_requests FOR EACH ROW EXECUTE FUNCTION public.guard_follow_request();